            } else {
                throw new Error('stat_data not found or empty');
            }
        } catch (error) {
            if (retries > 0) {
                setTimeout(() => fetchData(msgId, retries - 1, delay), delay);
            } else {
                populate(initialData); // Final fallback
            }
        }
    };
    try {
        const msgId = typeof getCurrentMessageId === 'function' ? getCurrentMessageId() : 0;
        (msgId === 0 || msgId === null) ? populate(initialData) : fetchData(msgId);
    } catch (e) {
        populate(initialData);
    }
})();
</script>
